  ui_story_31780401_126_dialog_content = "É fácil ganhar a confiança deles, desde que você domine a arte de se comunicar com eles.",
  ui_story_31780401_127_dialog_content = "...",
  ui_story_31780401_128_dialog_content = "Jovem, quem é você?",
  ui_story_31780401_129_dialog_content = "Eu? O nome é Vic.",
  ui_story_31780401_130_dialog_content = "Vic? Por que isso soa tão familiar?",
  ui_story_31780401_131_dialog_content = "Espere, não me diga que você é...?",
