  ui_story_31780401_140_dialog_content = "Contanto que você esteja disposto a me ensinar como me comunicar com feras maravilhosas.",
  ui_story_31780401_141_dialog_content = "Certo!",
  ui_story_31780401_142_dialog_content = "Você pode me encontrar na clínica veterinária em Umbraton na maioria dos dias.",
  ui_story_31780401_143_dialog_content = "Então é um acordo. Eu irei visitá-lo no futuro.",
  ui_story_31780401_144_dialog_content = "Eu ainda preciso ir para Lumopolis hoje, então vou me despedir.",
