  ui_story_31780401_147_dialog_content = "O que mais podemos fazer? Pekos não são baratos.",
  ui_story_31780401_148_dialog_content = "Eu já soltei um. Isso é tecnicamente o suficiente para eu acabar na prisão de Lumopolis por um ano.",
