  ui_story_31780401_152_dialog_content = "Eu não dou a mínima para Peko sobre aquele velho.",
  ui_story_31780401_153_dialog_content = "Mas se aquele Peko morder alguém de novo, com certeza será abatido.",
  ui_story_31780401_154_dialog_content = "Era inevitável se eu não tivesse intervindo, considerando como parecia.",
  ui_story_31780401_155_dialog_content = "Entendi!",
  ui_story_31780401_156_dialog_content = "Você domou o Peko para garantir que ele sobreviveria.",
  ui_story_31780401_157_dialog_content = "Eu tenho que dizer, Vic, você realmente me impressionou hoje!",
  ui_story_31780401_158_dialog_content = "A propósito, nunca soube que você trabalhava em uma clínica veterinária.",
  ui_story_31780401_159_dialog_content = "Hah, você realmente pode ser bastante ingênuo às vezes.",
  ui_story_31780401_160_dialog_content = "Hã?",
  ui_story_31780401_161_dialog_content = "Isso foi apenas uma pequena mentira - não quero ver aquele cara nunca mais.",
  ui_story_31780401_162_dialog_content = "Já estou de mãos dadas com Fia e Shira. Eu não suportaria ter outro aprendiz como ele me arrastando para baixo.",
  ui_story_31780401_163_dialog_content = "PlayerName, você ainda é muito jovem para entender completamente os caminhos do mundo...",
  ui_story_31780401_164_dialog_content = "... Suponho que sim.",
  ui_story_31780601_1_dialog_content = "<color=#e8d9bb>Ronco...</color>",
  ui_story_31780601_2_dialog_content = "Ei, que som é esse? Você está captando algo com esses seus sentidos especiais?",
  ui_story_31780601_3_dialog_content = "Esse é o som do meu estômago roncando!",
  ui_story_31780601_4_dialog_content = "Também estou morrendo de fome... Já acabamos com todas as rações secas que trouxemos conosco.",
  ui_story_31780601_5_dialog_content = "E você ainda está com fome?! Não acredito que você comeu todas as rações sozinho!",
  ui_story_31780601_6_dialog_content = "Huh? E quando você alega que eu fiz isso? Hic—",
  ui_story_31780601_7_dialog_content = "Quando eu estava ocupado tentando detectar o tesouro!",
  ui_story_31780601_8_dialog_content = "Heheh, então você me viu, né? Estranho... Eu até esperei você virar de costas.",
  ui_story_31780601_9_dialog_content = "Você tem ideia do quão alto é o barulho da sua mastigação?!",
  ui_story_31780601_10_dialog_content = "Bem, eu tenho tentado te manter motivado todo esse tempo, criança. É cansativo!",
  ui_story_31780601_11_dialog_content = "Huh? Eu ainda não ouvi uma palavra de motivação de você!",
  ui_story_31780601_12_dialog_content = "Eu estive torcendo por você... em meu coração.",
  ui_story_31780601_13_dialog_content = "... Se eu pudesse voltar no tempo, de jeito nenhum escolheria ir ao mar com você, Vic.",
  ui_story_31780601_14_dialog_content = "<color=#e8d9bb>Algumas horas antes...</color>",
  ui_story_31780601_15_dialog_content = "Ah, não são Vic e Shira ali na frente? Faz um tempo que não nos encontramos. Eu deveria ir lá e cumprimentá-los.",
  ui_story_31780601_16_dialog_content = "—Não estou realmente de bom humor.",
  ui_story_31780601_17_dialog_content = "É o tesouro de uma vida! Assim que colocarmos as mãos nele, todos terão uma parte igual - e isso inclui você também, meu pequeno!",
  ui_story_31780601_18_dialog_content = "Bem... faça uma boa viagem.",
  ui_story_31780601_19_dialog_content = "Você não se importa com seu mestre? Pense em mim naqueles mares traiçoeiros e solitários - o perigo, o horror! E se um monstro marinho atacar? Eu preciso de você lá para me ajudar a cuidar desse tipo de coisa!",
  ui_story_31780601_20_dialog_content = "Claro. Isso é ainda mais motivo para você ir por conta própria.",
  ui_story_31780601_21_dialog_content = "Vocês dois realmente têm uma relação estranha para mestre e discípulo...",
  ui_story_31780601_22_dialog_content = "PlayerName! Maravilhoso! Vamos enfrentar os mares juntos!",
  ui_story_31780601_23_dialog_content = "Acertar o quê agora?",
  ui_story_31780601_24_dialog_content = "Os altos mares, meu garoto! Você já deve ter ouvido os rumores? O tesouro perdido do Rei Pirata ressurgiu mais uma vez!",
  ui_story_31780601_25_dialog_content = "O todo-poderoso Rei Pirata saqueou inúmeros tesouros em seu tempo e os escondeu em um local misterioso que apenas os exploradores mais corajosos e inteligentes poderiam encontrar.",
  ui_story_31780601_26_dialog_content = "Isso parece uma história de um dos livros ilustrados de Fia...",
  ui_story_31780601_27_dialog_content = "Uma fonte confiável me informou que este tesouro de ouro está escondido nas profundezas das ondas do oceano!",
  ui_story_31780601_28_dialog_content = "Não tenho tanta certeza disso, quer dizer, eu sei qual é a sua definição de confiável...",
  ui_story_31780601_29_dialog_content = "Sou apenas um velho solitário tentando criar dois adoráveis aprendizes sozinho - minhas pernas estão grisalhas, minhas orelhas estão nodosas, meus olhos estão velhos e tortos.",
  ui_story_31780601_30_dialog_content = "Você tem sido preguiçoso o tempo todo! Fia e eu somos os que cuidam de VOCÊ!",
  ui_story_31780601_31_dialog_content = "Ahem, bem, agora que finalmente descobri tudo sobre o tesouro, estou pronto para enfrentar uma série de armadilhas piratas, se necessário, tudo para ganhar um pouco de dinheiro para o leite do meu querido filho, Fia!",
  ui_story_31780601_32_dialog_content = "Fia não é mais um bebê que só bebe leite.",
  ui_story_31780601_33_dialog_content = "PlayerName, com certeza você pode entender, tendo que cuidar de uma Colossus tão enorme e tudo mais. É como ter um buraco no bolso, e eu tenho dois deles!",
  ui_story_31780601_34_dialog_content = "Bem, agora que você mencionou... Na verdade, eu queria dar uma melhorada na Colossus recentemente, mas não consegui levantar os fundos para tornar isso possível...",
  ui_story_31780601_35_dialog_content = "Mas com suas habilidades psíquicas únicas, com certeza encontraremos o tesouro rapidamente! Tesouro dourado, aqui vamos nós!",
  ui_story_31780601_36_option_content = "Mostre-me o tesouro!",
  ui_story_31780601_37_dialog_content = "Shira, espere aqui - voltaremos com as mercadorias antes que você perceba!",
  ui_story_31780601_38_option_content = "Posso ficar com todo o tesouro para mim mesmo?",
  ui_story_31780601_39_dialog_content = "Exatamente o que eu esperaria de um Celestita—você captou o aroma genuíno das intenções mais sinceras do meu coração.",
  ui_story_31780601_40_dialog_content = "...",
  ui_story_31780601_41_dialog_content = "Bocejo... Apenas certifique-se de voltar vivo.",
  ui_story_31780601_42_dialog_content = "De acordo com minha fonte, o tesouro deve estar localizado nesta área do mar. Você está me dizendo que realmente não consegue sentir nada aqui?",
  ui_story_31780601_43_dialog_content = "Não, nada. Talvez essa área seja muito grande ou profunda... talvez minhas habilidades psíquicas sejam muito fracas, ou talvez... o tesouro simplesmente não exista.",
  ui_story_31780601_44_dialog_content = "Estou morrendo de fome... e estou morrendo de sede aqui... Vamos voltar...",
  ui_story_31780601_45_dialog_content = "Olha! Há uma luz brilhando na água!",
  ui_story_31780601_46_dialog_content = "A luz está fluindo em nossa direção. Será que são... águas-vivas?",
  ui_story_31780601_47_dialog_content = "Eu não pensei que encontraríamos esse tipo de água-viva aqui.",
  ui_story_31780601_48_dialog_content = "É algum tipo de espécie rara? A luz que eles emitem parece tão diferente de tudo que já vi antes.",
  ui_story_31780601_49_dialog_content = "De fato, não são águas-vivas comuns. Na verdade, essas criaturas milagrosas podem até nos levar ao tesouro!",
  ui_story_31780601_50_dialog_content = "Olha, é quase como se eles estivessem colocando as cabeças para fora da água para dar oi.",
  ui_story_31780601_51_dialog_content = "Ei, você, fofinha água-viva! Como você está hoje?",
  ui_story_31780601_52_dialog_content = "Cuidado! Essas águas-vivas são venenosas! Basta um toque e—",
  ui_story_31780601_53_dialog_content = "É tão macio... tão suave... tão... urgh...",
  ui_story_31780601_54_dialog_content = "Ei, por que você tocou nisso?!",
  ui_story_31780601_55_dialog_content = "...",
  ui_story_31780601_56_dialog_content = "...",
  ui_story_31780601_57_dialog_content = "PlayerName... Acorda, PlayerName.",
  ui_story_31780601_58_dialog_content = "Urgh... O que aconteceu?",
  ui_story_31780601_59_dialog_content = "Você desmaiou por causa da picada de uma água-viva, e depois o cardume de águas-vivas arrastou nossa jangada até aqui.",
  ui_story_31780601_60_dialog_content = "Está tão escuro aqui. Onde estamos?",
  ui_story_31780601_61_dialog_content = "Parece ser uma caverna secreta de algum tipo. Acredito que este pode ser o local onde o tesouro está escondido!",
  ui_story_31780601_62_dialog_content = "Não consigo ver nenhum tesouro por aqui, mas com certeza posso sentir uma presença perigosa ao nosso redor.",
  ui_story_31780601_63_dialog_content = "Enquanto eu estiver aqui, você pode rir diante do perigo.",
  ui_story_31780601_64_dialog_content = "Se realmente não temos nada a temer, por que você está se escondendo atrás de mim?",
  ui_story_31780601_65_dialog_content = "Bem, isso é porque não é muito seguro aqui, não é mesmo?",
  ui_story_31780601_66_dialog_content = "...",
  ui_story_31780601_67_dialog_content = "Heheh, estou brincando. Você estará seguro - seguro nas mãos capazes de um destemido extrozoólogo extraordinário!",
  ui_story_31780601_68_dialog_content = "Tudo que eu preciso fazer é invocar minhas feras maravilhosas, e quaisquer demônios que possamos enfrentar, nunca teremos que temer, nem mesmo por um segundo!",
  ui_story_31780601_69_dialog_content = "Onde estão seus amigos bestas maravilhosos? Por que você ainda não os invocou?",
  ui_story_31780601_70_dialog_content = "Ah, bem, o sinal aqui não está tão bom...",
  ui_story_31780601_71_dialog_content = "Kree... Kree...!",
  ui_story_31780601_72_dialog_content = "Ah! Que som é esse? A caverna inteira está tremendo!",
  ui_story_31780601_73_dialog_content = "Estou com um mau pressentimento sobre isso. Deve haver um monstro terrível nos esperando mais à frente!",
  ui_story_31780601_74_dialog_content = "Não preciso de habilidades psíquicas para saber que precisamos sair daqui rapidamente!",
  ui_story_31780601_75_dialog_content = "Espere aí. Um monstro assim não apareceria sem motivo! Devemos estar nos aproximando do tesouro!",
  ui_story_31780601_76_dialog_content = "Você tá falando sério que ainda pensa em tesouro quando sua vida está em jogo?",
  ui_story_31780601_77_dialog_content = "Como eu disse, você não precisa se preocupar com nada enquanto eu estiver por perto.",
  ui_story_31780601_78_dialog_content = "Coruja Lutumi!",
  ui_story_31780601_79_dialog_content = "Uhu-uhu-uhu!",
  ui_story_31780601_80_dialog_content = "Bica!",
  ui_story_31780601_81_dialog_content = "Oi-oi!",
  ui_story_31780601_82_dialog_content = "Bolinha de Pelos!",
  ui_story_31780601_83_dialog_content = "Chirrrp—!",
  ui_story_31780601_84_dialog_content = "Transforme-se!",
  ui_story_31780601_85_dialog_content = "Chirrrp—!",
  ui_story_31780601_86_dialog_content = "Uau... Eles realmente vieram!",
  ui_story_31780601_87_dialog_content = "Apenas fique atrás de mim e não tenha medo - eu vou te proteger!",
  ui_story_31780601_88_dialog_content = "(Estranho. Por que ele parece tão intenso de repente?)",
  ui_story_31780601_89_dialog_content = "Continue seguindo em frente—o tesouro está bem à frente!",
  ui_story_31780601_90_dialog_content = "Ei, o que é essa coisa brilhante no chão?",
  ui_story_31780601_91_dialog_content = "Ouro! É ouro!",
  ui_story_31780601_92_dialog_content = "Aquele imenso mar de luz dourada brilhando à frente... Você vê isso?!",
  ui_story_31780601_93_dialog_content = "É o tesouro! Vamos buscá-lo!",
  ui_story_31780601_94_dialog_content = "Cree! Kree—!",
  ui_story_31780601_95_dialog_content = "Ahhhhh!!!",
  ui_story_31780601_96_dialog_content = "Ouroboros?!",
  ui_story_31780601_97_dialog_content = "Não voou com o Eulogoz? O que está fazendo aqui?",
  ui_story_31780601_98_dialog_content = "Kree, kree—kree!",
  ui_story_31780601_99_dialog_content = "Uau!",
  ui_story_31780601_100_dialog_content = "Cuidado!",
  ui_story_31780601_101_dialog_content = "O Ouroboros pegou minha moeda de ouro!",
  ui_story_31780601_102_dialog_content = "Está guardando este tesouro.",
  ui_story_31780601_103_dialog_content = "Estranho, nunca ouvi falar que o Ouroboros tinha uma inclinação para acumular ouro.",
  ui_story_31780601_104_dialog_content = "Parece que precisamos derrotá-lo antes de podermos reivindicar o tesouro.",
  ui_story_31780601_105_dialog_content = "Derrotar o Ouroboros? Como vamos fazer isso?",
  ui_story_31780601_106_dialog_content = "Não diga mais nada, o Ouroboros se acalmou um pouco... Só precisamos aproveitar o momento certo...",
  ui_story_31780601_107_dialog_content = "Nem pense em machucá-lo. Eu me lembro do Ouroboros como uma criatura gentil e bondosa. Acho que ele não nos atacará.",
  ui_story_31780601_108_dialog_content = "Talvez o tesouro tenha corrompido sua mente e o transformado em um demônio ganancioso que rouba tesouros...",
  ui_story_31780601_109_dialog_content = "Cree, cree!",
  ui_story_31780601_110_dialog_content = "Lutumi Owl, Bica, Grande Bolinha de Pelos - derrube-a!",
  ui_story_31780601_111_dialog_content = "...",
  ui_story_31780601_112_dialog_content = "...",
  ui_story_31780601_113_dialog_content = "...",
  ui_story_31780601_114_dialog_content = "Ei! Não se atreva!",
  ui_story_31780601_115_dialog_content = "Kree, kree—kree!",
  ui_story_31780601_116_dialog_content = "Ei, calma, calma... Não estamos aqui para roubar seu ouro, amigo, estamos apenas aqui para dar uma olhada... Ei, talvez até possamos nos tornar melhores amigos? O que você acha?",
  ui_story_31780601_117_dialog_content = "Kree, kree?",
  ui_story_31780601_118_dialog_content = "Apenas confie em mim! Eu SOU o principal extrozoólogo de todo o continente - comunicar-me com Ouroboros é uma das minhas inúmeras habilidades.",
  ui_story_31780601_119_dialog_content = "Kree—",
  ui_story_31780601_120_dialog_content = "Vamos lá, deixe-me te dar um abraço.",
  ui_story_31780601_121_dialog_content = "Vic, o que você acha que está fazendo?",
  ui_story_31780601_122_dialog_content = "Observe atentamente! Estou prestes a usar minhas habilidades secretas de Encantador de Ouroboros—",
  ui_story_31780601_123_dialog_content = "O primeiro movimento é a Postura do Beliscador de Rosto, onde se usa ambas as mãos para acariciar a bochecha, aquecendo-a instantaneamente!",
  ui_story_31780601_124_dialog_content = "O segundo movimento é o Andar na Ponta dos Pés, onde você fica na ponta dos pés e caminha para frente e para trás nas costas dele, levando até mesmo o mais cauteloso Ouroboros a um estado de relaxamento!",
  ui_story_31780601_125_dialog_content = "Não é comum ver você levar algo tão a sério. Acho que quando se trata de tesouros, você realmente tem um lado confiável.",
  ui_story_31780601_126_dialog_content = "Kree, kree, kree!",
  ui_story_31780601_127_dialog_content = "Veja como os olhos do Ouroboros se estreitaram? Isso significa que ele está começando a se sentir extremamente confortável.",
  ui_story_31780601_128_dialog_content = "Kree!",
  ui_story_31780601_129_dialog_content = "Ei?! Como ele conseguiu se transformar em um ovo?",
  ui_story_31780601_130_dialog_content = "Talvez tenha se sentido tão confortável que acabou adormecendo?",
  ui_story_31780601_131_dialog_content = "Então... todo esse ouro é nosso agora?",
  ui_story_31780601_132_dialog_content = "Isso mesmo, você pode arrumar tudo e levar daqui para fora.",
  ui_story_31780601_133_dialog_content = "Wahahahaha! Finalmente tenho dinheiro suficiente para consertar a Colossus! Tem o suficiente aqui para revestir o interior inteiro de Soroz com ouro!",
  ui_story_31780601_134_dialog_content = "Oh, céus. Por onde devo começar as reformas? A ponte? Os geradores? Talvez eu deva construir uma extensão no meu quarto?",
  ui_story_31780601_135_dialog_content = "Você sabe que eu não sou o tipo de cara que gosta de esbanjar, mas não faria mal deixar meu quarto um pouco mais confortável, não é?",
  ui_story_31780601_136_dialog_content = "Limpe a boca, você está babando.",
  ui_story_31780601_137_dialog_content = "Heheheh, desculpe, acho que me empolguei um pouco!",
  ui_story_31780601_138_dialog_content = "Hã? Por que você não está pegando o ouro? Você está parado aí olhando para ele como se não o quisesse.",
  ui_story_31780601_139_dialog_content = "Acho que já está na hora de você acordar agora.",
  ui_story_31780601_140_dialog_content = "Huh? O que você está falando?",
  ui_story_31780601_141_dialog_content = "Estou dizendo... nada disso é real... isso tudo é uma ilusão...",
  ui_story_31780601_142_dialog_content = "Err... Minha cabeça dói...",
  ui_story_31780601_143_dialog_content = "Pfffff! O que toda essa grama está fazendo na minha boca?!",
  ui_story_31780601_144_dialog_content = "Essa é a erva que salvou sua vida, meu garoto! Limpe sua boca agora, todo o remédio está saindo.",
  ui_story_31780601_145_dialog_content = "Urgh... Eu... Onde estou?",
  ui_story_31780601_146_dialog_content = "Você está na balsa, é claro! Onde mais você estaria?",
  ui_story_31780601_147_dialog_content = "A balsa? Que balsa?",
  ui_story_31780601_148_dialog_content = "A coisa de madeira na qual estamos flutuando agora! Você perdeu a memória?",
  ui_story_31780601_149_dialog_content = "N-Não... Eu me lembro... Eu me lembro que fomos levados para uma caverna por águas-vivas...",
  ui_story_31780601_150_dialog_content = "Ah, as águas-vivas ainda estão aqui.",
  ui_story_31780601_151_dialog_content = "A caverna que você mencionou estava cheia de ouro e protegida pelo Ouroboros, correto?",
  ui_story_31780601_152_dialog_content = "Sim! Você também estava lá!",
  ui_story_31780601_153_dialog_content = "Eu nunca estive naquele lugar, mas você continuou gritando—",
  ui_story_31780601_154_dialog_content = "Você disse que ia levar todo o tesouro e revestir o interior inteiro de Soroz com ouro. E algo sobre construir uma extensão no seu quarto. Realmente parecia um sonho maravilhoso.",
  ui_story_31780601_155_dialog_content = "Um sonho? Não poderia ter sido tudo apenas um sonho!",
  ui_story_31780601_156_dialog_content = "É tudo por causa da água-viva - a Água-viva Tecelã de Sonhos. Ela tem a habilidade de ler os pensamentos e emoções de quem quer que a toque.",
  ui_story_31780601_157_dialog_content = "Eles possuem o poder de criar as visões mais perfeitas ou mais horrendas nas mentes dos afetados, baseadas em seus medos e desejos mais profundos.",
  ui_story_31780601_158_dialog_content = "Então... Então meu desejo mais profundo é... por ouro?",
  ui_story_31780601_159_dialog_content = "Isso mesmo! Como o último Celestita, tudo o que você consegue pensar é em ouro, sem nenhuma grande ambição ou ideal elevado à vista!",
  ui_story_31780601_160_dialog_content = "Err... Bem... Eu só...",
  ui_story_31780601_161_dialog_content = "Heehee! Somos só nós dois aqui, você não precisa se explicar para mim.",
  ui_story_31780601_162_dialog_content = "Eu te entendo totalmente. Se eu tivesse tocado naquela coisa, provavelmente teria tido o mesmo sonho!",
  ui_story_31780601_163_dialog_content = "Não é isso. Eu não sou uma pessoa gananciosa. Aquele sonho deve ter sido algum tipo de soluço cerebral!",
  ui_story_31780601_164_dialog_content = "Por que mais você arriscaria sua vida e seus membros para vir comigo nesta jangada instável?",
  ui_story_31780601_165_dialog_content = "Eu estava preocupado que pudesse ser muito perigoso para você zarpar sozinho!",
  ui_story_31780601_166_dialog_content = "Então, você ainda teria vindo comigo se não houvesse tesouro para ser encontrado?",
  ui_story_31780601_167_option_content = "Acho que não.",
  ui_story_31780601_168_dialog_content = "(Suspiro) Então o tesouro do Rei dos Piratas realmente era apenas uma lenda... Bem, essa foi a última vez que acredito em tudo que leio nos livros ilustrados de Fia!",
  ui_story_31780601_169_dialog_content = "Você tirou tudo isso de um livro de histórias infantil?!",
  ui_story_31780601_170_dialog_content = "Aliás, eu não tenho absolutamente nenhuma ideia de qual direção estamos à deriva agora.",
  ui_story_31780601_171_dialog_content = "Eu estava fazendo tudo o que podia para te salvar, então naturalmente perdi a noção de para onde a maré estava nos levando.",
  ui_story_31780601_172_dialog_content = "Precisamos pensar em uma maneira de voltar para casa.",
  ui_story_31780601_173_dialog_content = "Sugestões?",
  ui_story_31780601_174_dialog_content = "Bem, sempre há o método mais primitivo, porém mais eficaz—",
  ui_story_31780601_175_dialog_content = "Socorro!!!"
}
return config
